\title{Oscillation Counting and the Exact Depth--Width Trade-off\\ for Rectifier Networks}
\author{Aristotle}
\date{8 September 2026}

\begin{document}
\maketitle

\begin{abstract}
We develop, from first principles, a complete and unconditional account of the depth--width trade-off for feed-forward networks with the rectified linear activation $\relu(t)=\max(t,0)$, using a single tool: the propagation of \emph{knots} (breakpoints of a piecewise affine function) through the layers of a network, matched against the number of \emph{oscillations} a target function forces upon any approximant.

On the lower-bound side we prove that a network of depth $L$ and width $w$ with one real input computes a continuous piecewise affine function with at most $2(2w+2)^L$ knots, and that any function within $1/4$ of the $k$-fold sawtooth tower $\tau^{\circ k}$ uniformly on $[0,1]$ has at least $(2^k-1)/2$ knots. Combining these gives the master inequality $2^k \le 4(2w+2)^L$. Specialising to $k=L^2+4$ yields a depth separation: $\tau^{\circ(L^2+4)}$ is computed exactly by a network of depth $L^2+4$ and width $3$ --- size $3(L^2+4)$, polynomial in $L$ --- while every depth-$L$ network approximating it within $1/4$ has width at least $2^{L-1}-1$.

We strengthen the separation to the $L^1$ norm (integrated error at least $\bigl(2^{k-1}-2(2w+2)^L\bigr)/(16\cdot 2^k)\to 1/32$), to a density statement (failure by more than $1/4$ at a $\bigl(\tfrac13-o(1)\bigr)$-fraction of the $2^k+1$ dyadic sample points), and to arbitrary input dimension via a restriction principle. Finally we prove a matching \emph{collapse} theorem delimiting how strong such separations can be: for every $c\ge1$ the entire height-$c$ tower is realised by a \emph{single} rectifier layer of width $2^c+1$, so $\tau^{\circ cL}$ is exact at depth $L$ and width $2^c+1$; the ``one extra layer'' form of the conjecture is false for sawtooth witnesses, and the maximal exactly computable tower height at depth $L$ and width $w$ is $\Theta(L\log w)$.
\end{abstract}

\section{Introduction}

Feed-forward networks with rectified linear units compute continuous piecewise affine functions, and nothing else. This makes the expressivity question concrete: which piecewise affine functions can a network of depth $L$ and width $w$ compute, and how does the answer change as we trade depth for width?

The folklore answer is that depth is exponentially more valuable than width, because complexity \emph{composes} multiplicatively across layers while it merely \emph{accumulates} additively within a layer. The canonical evidence is the iterated sawtooth: the tent map $\tau$ is one narrow layer, and $k$ layers produce a function with $2^{k-1}$ teeth.

Two questions remain, and this paper answers both.
\begin{enumerate}
\item \emph{How strong is the separation, precisely?} We prove an unconditional master inequality $2^k\le 4(2w+2)^L$ for approximation within $1/4$, and derive exponential lower bounds in sup-norm, in $L^1$, in density on a sample grid, and in arbitrary input dimension.
\item \emph{How strong can it be?} We prove a matching upper bound showing that the naive ``depth $L{+}1$ versus depth $L$'' conjecture is \emph{false} for the canonical witnesses: sawtooth towers of height $L+O(\log L)$ collapse to depth $L$ at polynomial size. The governing parameter is the ratio $k/L$, and we determine the exact law $\Theta(L\log w)$ for exact computability.
\end{enumerate}

\section{Setting and definitions}

Throughout, $\relu(t)=\max(t,0)$.

\begin{definition}[Layer units]
Fix $w\in\N$. The families of \emph{layer-$L$ unit functions} of a rectifier network with one real input are defined inductively. The single-element family $u_1(x)=x$ is a layer-$0$ family. If $(u_1,\dots,u_n)$ is a layer-$L$ family, $m\le w$, $W\in\R^{m\times n}$ and $b\in\R^m$, then
\[
v_j(x)=\relu\Bigl(\sum_{i=1}^n W_{ji}u_i(x)+b_j\Bigr),\qquad j=1,\dots,m,
\]
is a layer-$(L{+}1)$ family.
\end{definition}

\begin{definition}[Networks]
$f:\R\to\R$ \emph{is a depth-$L$, width-$w$ network}, written $f\in\Net(w,L)$, if there is a layer-$L$ family $(u_1,\dots,u_n)$ and $c\in\R^n$, $d\in\R$ with $f(x)=\sum_i c_iu_i(x)+d$. The size of the network is at most $wL$ hidden units, and $\Net(w,L)\subseteq\Net(w',L)$ for $w\le w'$.
\end{definition}

\begin{definition}[Sawtooth]
The tent map is
\[
\tau(y)=2\relu(y)-4\relu\bigl(y-\tfrac12\bigr)+2\relu(y-1),
\]
i.e.\ $\tau(y)=0$ off $[0,1]$, $\tau(y)=2y$ on $[0,\tfrac12]$ and $\tau(y)=2-2y$ on $[\tfrac12,1]$. Write $\tau^{\circ k}$ for the $k$-fold composite, the \emph{sawtooth tower of height $k$}. In particular $\tau\in\Net(3,1)$.
\end{definition}

\begin{definition}[Affine on an interval; knot set]
$f$ is \emph{affine on $[u,v]$}, written $\Aff(f;u,v)$, if $f(x)=ax+b$ on $[u,v]$ for some $a,b$. For a finite $S\subset\R$ we write $\PWA(S,f)$ if for all $0\le u\le v\le 1$ such that every $z\in S$ satisfies $z\le u$ or $v\le z$, we have $\Aff(f;u,v)$: the function is straight on every subinterval of $[0,1]$ whose interior misses $S$. If $\PWA(S,f)$ and $S\subseteq T$ then $\PWA(T,f)$.
\end{definition}

\section{The knot calculus}

\begin{lemma}\label{lem:affine}
For all $a,b$ we have $\PWA(\varnothing,\ x\mapsto ax+b)$.
\end{lemma}

\begin{lemma}[Affine read-outs are free]\label{lem:readout}
If $\PWA(S,f_i)$ for $i=1,\dots,n$ with a common finite $S$, then $\PWA\bigl(S,\ x\mapsto\sum_i c_if_i(x)+d\bigr)$ for all $c\in\R^n$, $d\in\R$.
\end{lemma}

\begin{proof}
Fix an admissible $[u,v]$ and write $f_i(x)=A_ix+B_i$ there. Then $\sum_ic_if_i(x)+d=(\sum_ic_iA_i)x+(\sum_ic_iB_i+d)$ on $[u,v]$.
\end{proof}

\begin{lemma}[No crossing, no kink]\label{lem:nocross}
Suppose $f(x)=Ax+B$ on $[p,q]$ and $[u,v]\subseteq[p,q]$. Let $\zeta=p$ if $A=0$ and $\zeta=-B/A$ otherwise. If $\zeta\le u$ or $v\le\zeta$, then $\Aff(\relu\circ f;u,v)$.
\end{lemma}

\begin{proof}
If $A=0$ then $\relu(f)=\relu(B)$ is constant. If $A>0$ and $\zeta\le u$, then $Ax+B\ge0$ on $[u,v]$, so $\relu\circ f=Ax+B$; if $v\le\zeta$ then $Ax+B\le0$ and $\relu\circ f\equiv 0$. The case $A<0$ is symmetric with the conclusions exchanged.
\end{proof}

\begin{theorem}[The rectifier step]\label{thm:relustep}
If $\PWA(S,f)$ then there is a finite $T$ with $|T|\le 2|S|+4$ and $\PWA(T,\relu\circ f)$.
\end{theorem}

\begin{proof}[Proof sketch]
Normalise $S$ to $S'=\{0,1\}\cup(S\cap[0,1])$, so $|S'|\le|S|+2$, $S'\subseteq[0,1]$ and still $\PWA(S',f)$. For $p\in S'$ let $\mathrm{nxt}(p)$ be the least element of $S'$ exceeding $p$ (or $1$); then $f$ is affine on $[p,\mathrm{nxt}(p)]$, and let $\mathrm{cross}(p)$ be the corresponding zero $\zeta$ of Lemma~\ref{lem:nocross}. Put $T=S'\cup\mathrm{cross}(S')$, so $|T|\le 2|S'|\le 2|S|+4$. Given admissible $[u,v]$ with $u<v$, let $p=\max\{z\in S':z\le u\}$ (well defined since $0\in S'$). Then $v\le\mathrm{nxt}(p)$, so $[u,v]\subseteq[p,\mathrm{nxt}(p)]$, and since $(u,v)$ misses $\mathrm{cross}(p)$, Lemma~\ref{lem:nocross} applies.
\end{proof}

\begin{remark}
The bound is the normalised form of ``at most one new knot per affine piece'': a function with $|S|$ knots has at most $|S|+1$ pieces in $[0,1]$, and an affine piece crosses zero at most once.
\end{remark}

\section{The knot budget of a network}

\begin{definition}
Let $\kappa(w,0)=0$ and $\kappa(w,L+1)=w\bigl(2\kappa(w,L)+4\bigr)$.
\end{definition}

\begin{theorem}[Layer-wise budget]\label{thm:budget}
If $(u_1,\dots,u_n)$ is a layer-$L$ family for width bound $w$, there is a finite $S$ with $|S|\le\kappa(w,L)$ and $\PWA(S,u_i)$ for every $i$. Consequently, if $f\in\Net(w,L)$ then $\PWA(S,f)$ for some $S$ with $|S|\le\kappa(w,L)$.
\end{theorem}

\begin{proof}
Induction. The input unit is affine, so $S=\varnothing$ works. For the step, let $S$ be a common knot set of the previous family. Each pre-activation has knot set $S$ by Lemma~\ref{lem:readout}; by Theorem~\ref{thm:relustep} each rectified unit $v_j$ has a knot set $T_j$ with $|T_j|\le2|S|+4$. Take $T=\bigcup_{j\le m}T_j$, so $|T|\le m(2|S|+4)\le w(2\kappa(w,L)+4)$. The statement for $f$ follows by applying Lemma~\ref{lem:readout} to the read-out.
\end{proof}

\begin{theorem}[Closed form]\label{thm:closed}
For all $w,L$: $\kappa(w,L)+2\le 2(2w+2)^L$. Hence a depth-$L$, width-$w$ network computes a piecewise affine function with at most $2(2w+2)^L$ knots.
\end{theorem}

\begin{proof}
Induction on $L$; the base is $2\le2$. For the step, $\kappa(w,L+1)+2=2w(\kappa(w,L)+2)+2\le 4w(2w+2)^L+2\le 2(2w+2)^{L+1}$, since $2(2w+2)^{L+1}-4w(2w+2)^L=4(2w+2)^L\ge4$.
\end{proof}

\section{Oscillation forces knots}

\begin{lemma}[An affine function cannot go low--high--low]\label{lem:osc}
Let $x_1<x_2<x_3$ and let $f$ be affine on $[x_1,x_3]$ with $f(x_1)\le\tfrac14$, $f(x_2)\ge\tfrac34$, $f(x_3)\le\tfrac14$. This is contradictory.
\end{lemma}

\begin{proof}
Write $f(x)=ax+b$. Then $a(x_2-x_1)\ge\tfrac12>0$ forces $a>0$, while $a(x_3-x_2)\le-\tfrac12<0$ forces $a<0$.
\end{proof}

The mirrored statement (high--low--high) has the same proof.

\begin{theorem}[Alternation costs knots]\label{thm:alt}
Let $\PWA(S,f)$ and $0\le p_0<p_1<\dots<p_m\le1$ with $f(p_j)\le\tfrac14$ for even $j$ and $f(p_j)\ge\tfrac34$ for odd $j$ (or vice versa). Then $m\le 2|S|+1$.
\end{theorem}

\begin{proof}[Proof sketch]
For each $t$ the triple $(p_{2t},p_{2t+1},p_{2t+2})$ shows a low--high--low or high--low--high pattern, so by Lemma~\ref{lem:osc} $f$ is not affine on $[p_{2t},p_{2t+2}]$; hence $(p_{2t},p_{2t+2})$ contains a point of $S$. Distinct triples overlap only at endpoints, so these knots are distinct, giving $\lfloor m/2\rfloor\le|S|$.
\end{proof}

\begin{lemma}[The tower alternates at dyadic points]\label{lem:dyadic}
For $k\ge0$ and integers $0\le i\le 2^k$,
\[
\tau^{\circ k}\!\left(\frac{i}{2^k}\right)=\begin{cases}0,& i\ \text{even},\\ 1,& i\ \text{odd}.\end{cases}
\]
\end{lemma}

\begin{proof}[Proof sketch]
Induction on $k$, using the two affine branches: $\tau(i/2^{k+1})=i/2^k$ when $i\le2^k$ and $2-i/2^k$ when $i\ge2^k$, and applying the induction hypothesis (in the second case after the reflection $y\mapsto 2-y$, which preserves the parity bookkeeping).
\end{proof}

\begin{theorem}[Approximation costs knots]\label{thm:approxknots}
If $\PWA(S,f)$ and $|f(x)-\tau^{\circ k}(x)|\le\tfrac14$ for all $x\in[0,1]$, then $2^k\le 2|S|+1$.
\end{theorem}

\begin{proof}
Take $p_j=j/2^k$, $j=0,\dots,2^k$. By Lemma~\ref{lem:dyadic} and the error bound, $f(p_j)\le\tfrac14$ for even $j$ and $f(p_j)\ge\tfrac34$ for odd $j$; apply Theorem~\ref{thm:alt} with $m=2^k$.
\end{proof}

Taking $f=\tau^{\circ k}$ shows that even an exact piecewise affine representation of the tower needs $(2^k-1)/2$ knots.

\section{The depth separation}

\begin{theorem}[Master inequality]\label{thm:master}
If $f\in\Net(w,L)$ and $|f(x)-\tau^{\circ k}(x)|\le\tfrac14$ for all $x\in[0,1]$, then $2^k\le 4(2w+2)^L$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:budget} pick $S$ with $|S|\le\kappa(w,L)$ and $\PWA(S,f)$. Theorem~\ref{thm:approxknots} gives $2^k\le2\kappa(w,L)+1$ and Theorem~\ref{thm:closed} gives $\kappa(w,L)\le2(2w+2)^L-2$.
\end{proof}

\begin{theorem}[The tower is cheap with depth]\label{thm:cheap}
For all $k\ge1$, $\tau^{\circ k}\in\Net(3,k)$: the height-$k$ tower is computed exactly by a network of depth $k$ and width $3$, with $3k$ hidden units.
\end{theorem}

\begin{proof}[Proof sketch]
One layer with biases $0,-\tfrac12,-1$ and read-out $(2,-4,2)$ applied to an incoming value $y$ produces $\tau(y)$ exactly. Stack such a layer on a subnetwork computing $\tau^{\circ(k-1)}$ and induct.
\end{proof}

\begin{theorem}[Depth separation]\label{thm:sep}
Let $L\ge1$ and let $f\in\Net(w,L)$ satisfy $|f(x)-\tau^{\circ(L^2+4)}(x)|\le\tfrac14$ for all $x\in[0,1]$. Then $2^L\le2w+2$, i.e.\ $w\ge2^{L-1}-1$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:master} with $k=L^2+4$ gives $2^{L^2+4}\le4(2w+2)^L$. If $2w+2<2^L$ then $(2w+2)^L<2^{L^2}$, so $16\cdot2^{L^2}\le4\cdot2^{L^2}$, a contradiction.
\end{proof}

\begin{corollary}[Separation summary]
For every $L\ge1$: the explicit function $\tau^{\circ(L^2+4)}$ is a network of depth $L^2+4$ and width $3$, hence of size $3(L^2+4)$, polynomial in $L$; and every depth-$L$ network uniformly within $1/4$ of it on $[0,1]$ has width at least $2^{L-1}-1$, hence size exponential in $L$.
\end{corollary}

\section{Three strengthenings}

\subsection{Average-case ($L^1$) separation}

\begin{lemma}\label{lem:affineint}
For $a<b$ and affine $g(x)=\alpha x+\beta$,
\[
\int_a^b|g|\ \ge\ \frac{(b-a)\max(|g(a)|,|g(b)|)}{8}.
\]
\end{lemma}

\begin{proof}[Proof sketch]
Assume $M=|g(a)|\ge|g(b)|$ (else reflect). Then $|\alpha|(b-a)\le 2M$, so $|g|\ge M/2$ on $[a,a+(b-a)/4]$; integrate over that quarter.
\end{proof}

\begin{lemma}[An affine piece cannot track a tent]\label{lem:tooth}
Let $\PWA(S,f)$ with $f$ continuous, $k\ge1$, and let $I_t=[2t/2^k,(2t+2)/2^k]$ be a full tooth whose interior contains no point of $S$. Then $\int_{I_t}|f-\tau^{\circ k}|\ge \dfrac{1}{16\cdot 2^k}$.
\end{lemma}

\begin{proof}[Proof sketch]
On $I_t$, $f$ is affine and $\tau^{\circ k}$ is the tent vanishing at the endpoints with value $1$ at the midpoint. By Lemma~\ref{lem:osc}, $f$ cannot be simultaneously within $1/4$ of $0,1,0$ at the three points, so on one half-tooth the affine error function has absolute value at least $1/2$ at an endpoint. Apply Lemma~\ref{lem:affineint} on that half-tooth of length $2^{-k}$.
\end{proof}

\begin{theorem}[$L^1$ lower bound]\label{thm:l1}
For $k\ge1$, $\PWA(S,f)$ with $f$ continuous,
\[
\int_0^1|f-\tau^{\circ k}|\ \ge\ \frac{2^{k-1}-|S|}{16\cdot 2^k};
\qquad\text{and for } f\in\Net(w,L),\quad
\int_0^1|f-\tau^{\circ k}|\ \ge\ \frac{2^{k-1}-2(2w+2)^L}{16\cdot 2^k}.
\]
\end{theorem}

\begin{proof}
There are $2^{k-1}$ disjoint teeth, at most $|S|$ of which contain a knot; apply Lemma~\ref{lem:tooth} to the rest and sum. The network form follows from Theorems~\ref{thm:budget} and \ref{thm:closed}.
\end{proof}

With $k=L^2+4$ and $w<2^{L-1}-1$ the bound tends to $1/32$: a subexponentially wide depth-$L$ network is wrong on average, not merely somewhere.

\subsection{Failure has positive density}

\begin{theorem}[Bad dyadic points]\label{thm:density}
Let $\PWA(S,f)$ and $k\ge0$, and let $\mathcal{B}$ be the number of $j\in\{0,\dots,2^k\}$ with $\bigl|f(j/2^k)-\tau^{\circ k}(j/2^k)\bigr|>\tfrac14$. Then $2^k\le 3(\mathcal{B}+|S|)+2$, i.e.\ $\mathcal{B}\ge\frac{2^k-2}{3}-|S|$. For $f\in\Net(w,L)$, $2^k\le 3\bigl(\mathcal{B}+2(2w+2)^L\bigr)+2$.
\end{theorem}

\begin{proof}[Proof sketch]
Partition the dyadic indices into blocks of three consecutive points. In a block containing no bad point, the values of $f$ realise a low--high--low or high--low--high pattern by Lemma~\ref{lem:dyadic}, forcing a knot in the corresponding interval by Lemma~\ref{lem:osc}. Distinct blocks are charged distinct knots, so at most $|S|$ blocks are free of bad points, while there are at least $(2^k-2)/3$ blocks.
\end{proof}

For $k=L^2+4$ and $w<2^{L-1}-1$ this gives $\mathcal{B}\ge(\tfrac13-o(1))2^k$.

\subsection{Arbitrary input dimension}

Let $\Net_D(w,L)$ denote depth-$L$, width-$w$ networks with input in $\R^D$, defined as above with input units $u_i(x)=x_i$.

\begin{theorem}[Restriction principle]\label{thm:restrict}
If $F\in\Net_D(w,L)$ and $a,v\in\R^D$, then $t\mapsto F(a+tv)$ belongs to $\Net(w,L)$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction on layers: restricting the input units yields the affine maps $t\mapsto a_i+tv_i$, which are absorbed into the weights and biases of the first hidden layer; later layers are unchanged, since restriction commutes with weighted sums and with $\relu$.
\end{proof}

\begin{theorem}[Dimension-free ridge separation]\label{thm:ridge}
Fix $D\ge1$, a coordinate $i_0$ and $L\ge1$. The ridge function $x\mapsto\tau^{\circ(L^2+4)}(x_{i_0})$ lies in $\Net_D(3,L^2+4)$, and every $F\in\Net_D(w,L)$ with $\bigl|F(x)-\tau^{\circ(L^2+4)}(x_{i_0})\bigr|\le\tfrac14$ for all $x\in[0,1]^D$ satisfies $2^L\le2w+2$, independently of $D$.
\end{theorem}

\begin{proof}
Restrict along $t\mapsto t\,e_{i_0}$, which stays in the cube for $t\in[0,1]$, and apply Theorems~\ref{thm:restrict} and \ref{thm:sep}.
\end{proof}

\section{How far can separations go? The collapse theorems}

\begin{theorem}[Double fold in one layer]\label{thm:double}
For all $y\in\R$,
\[
\tau(\tau(y))=4\relu(y)-8\relu\bigl(y-\tfrac14\bigr)+8\relu\bigl(y-\tfrac12\bigr)-8\relu\bigl(y-\tfrac34\bigr)+4\relu(y-1).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Both sides vanish for $y\le0$ and for $y\ge1$ (for the right side because the coefficients and their first moment both sum to zero), and on each quarter interval both sides are affine with slopes $4,-4,4,-4$ and matching endpoint values.
\end{proof}

\begin{theorem}[Affine pieces of a tower]\label{thm:pieces}
For $c\ge0$, $0\le m<2^c$ and $y\in[m/2^c,(m+1)/2^c]$,
\[
\tau^{\circ c}(y)=\begin{cases}2^cy-m,& m\ \text{even},\\ (m+1)-2^cy,& m\ \text{odd},\end{cases}
\]
and $\tau^{\circ c}(y)=0$ for $y\le0$ and for $y\ge1$ when $c\ge1$.
\end{theorem}

\begin{theorem}[One layer realises an entire tower]\label{thm:onelayer}
For $c\ge1$ and all $y\in\R$,
\[
\tau^{\circ c}(y)=\sum_{i=0}^{2^c}a^{(c)}_i\relu\!\left(y-\frac{i}{2^c}\right),
\qquad
a^{(c)}_i=\begin{cases}2^c,& i=0\ \text{or}\ i=2^c,\\ (-1)^i2^{c+1},&\text{otherwise}.\end{cases}
\]
Hence $\tau^{\circ c}\in\Net(2^c+1,1)$.
\end{theorem}

\begin{proof}[Proof sketch]
Both sides vanish for $y\le0$. On the $m$-th dyadic interval the right side is $\bigl(\sum_{i\le m}a^{(c)}_i\bigr)y-\sum_{i\le m}a^{(c)}_i\,i/2^c$; telescoping the alternating coefficients gives $\sum_{i\le m}a^{(c)}_i=(-1)^m2^c$ and $\sum_{i\le m}a^{(c)}_i\,i/2^c=m$ for even $m$, $-(m+1)$ for odd $m$, matching Theorem~\ref{thm:pieces}. The total sum and total first moment vanish (this is where the halved end coefficients matter), so the right side is $0$ for $y\ge1$.
\end{proof}

\begin{theorem}[Collapse of the one-step witness]\label{thm:collapse}
For $L\ge2$, $\tau^{\circ(L+1)}\in\Net(5,L)$: the canonical depth-$(L{+}1)$ witness is computed \emph{exactly} by a network of depth $L$ and width $5$, with $5L$ hidden units. In particular the same function lies in $\Net(3,L+1)$ and in $\Net(5,L)$, so no exponential-in-$L$ size lower bound can hold for depth-$L$ approximation of this witness family.
\end{theorem}

\begin{proof}
Use one collapsed layer (Theorem~\ref{thm:double}) to compute $\tau^{\circ2}$, then $L-1$ sawtooth layers of width $3\le5$ on top.
\end{proof}

\begin{theorem}[General collapse; free logarithmic gaps]\label{thm:gencollapse}
For $c\ge1$ and $L\ge2$: $\tau^{\circ cL}\in\Net(2^c+1,L)$ and $\tau^{\circ(L+c-1)}\in\Net(2^c+1,L)$. If moreover $2^c\le L$, then $\tau^{\circ(L+c-1)}\in\Net(L+1,L)$: a depth-$L$ network with $O(L^2)$ units computes exactly a tower of height $L+\lfloor\log_2L\rfloor-1$.
\end{theorem}

\begin{theorem}[Tower-height bracket]\label{thm:bracket}
Fix $c\ge1$, $L\ge1$ and width $w=2^c+1$. Then $\tau^{\circ cL}\in\Net(w,L)$, and $\tau^{\circ k}\in\Net(w,L)$ implies $k\le(c+3)L+2$. Hence the maximal exactly computable tower height satisfies $cL\le k^\star\le(c+3)L+2$: it is $\Theta(L\log w)$.
\end{theorem}

\begin{proof}
The lower bound is Theorem~\ref{thm:gencollapse}. For the upper bound apply Theorem~\ref{thm:master} with zero error: $2^k\le4\bigl(2(2^c+1)+2\bigr)^L\le4\cdot2^{(c+3)L}$.
\end{proof}

\begin{corollary}
At width $5$ the achievable height satisfies $2L\le k^\star\le4L+2$; no depth-$L$ width-$5$ network computes $\tau^{\circ(L^2+4)}$ once $L\ge7$, consistently with Theorem~\ref{thm:sep}. Moreover, since the depth-$L$ width-$5$ network of Theorem~\ref{thm:collapse} computes $\tau^{\circ(L+1)}$ exactly, Theorem~\ref{thm:approxknots} forces its knot set to satisfy $2^{L+1}\le2|S|+1$: the exponential growth of the knot budget in $L$ is genuinely attained.
\end{corollary}

\section{Discussion}

\subsection{What decides a separation: the ratio $k/L$}

Theorems~\ref{thm:master} and \ref{thm:bracket} together give an essentially complete picture for sawtooth witnesses.

\begin{center}
\begin{tabular}{ll}
\toprule
Tower height $k$ & Status at depth $L$\\
\midrule
$k\le L$ & trivially exact at width $3$\\
$k=L+O(\log L)$ & exact at width $O(L)$: polynomial size\\
$k=cL$, $c$ constant & exact at width $2^c+1$: polynomial size\\
$k/L\to\infty$ & width must satisfy $2w+2\ge 2^{k/L}/4^{1/L}$: superpolynomial\\
$k=L^2+4$ & width $\ge 2^{L-1}-1$: exponential\\
\bottomrule
\end{tabular}
\end{center}

The conjecture ``depth $L{+}1$ beats depth $L$ exponentially'' is therefore false for the canonical witness family, in the strongest sense: an exact depth-$L$ representation of width $5$ exists. Any proof of a one-step exponential separation must use a genuinely different witness family, since oscillation count can grow by at most a bounded factor per layer at fixed width, and a single layer already contributes a factor $2^c$ at width $2^c+1$.

\subsection{Why knot counting is the right invariant}

Knot count is subadditive under the operations a network performs, with per-layer factor $2w$ up to additive slack, and the factor is essentially attained: the width-$(2^c+1)$ layer achieves $2^c$ against the permitted $2^{c+2}$. On the other side, oscillation is a lower bound on knots that is tight for the sawtooth, which has exactly $2^k$ affine pieces and exactly $2^k$ alternations. The two sides differ only in the base of the exponential, which is precisely what the bracket of Theorem~\ref{thm:bracket} records.

\subsection{Robustness and scope}

The separation survives passing from $L^\infty$ to $L^1$ (Theorem~\ref{thm:l1}); it holds at a positive density of sample points (Theorem~\ref{thm:density}); and it is dimension-free for ridge witnesses (Theorem~\ref{thm:ridge}). The tolerance $1/4$ is a convenience: the argument works for any fixed $\varepsilon<1/2$ with bands $[0,\varepsilon]$ and $[1-\varepsilon,1]$.

The results are statements about architectures, not about optimisation: a shallow architecture lacks the capacity, however it is trained. Conversely, the collapse theorems caution against over-reading depth-separation folklore: $\log_2 w$ folds per layer are free, so depth pays exponentially only when the required composition depth exceeds the available depth by a super-constant factor.

\subsection{Algorithmic reading}

The proofs are constructive. Evaluating $\kappa(w,\cdot)$ takes $O(L)$ arithmetic steps and certifies an upper bound on the number of pieces; the single comparison $2^k>4(2w+2)^L$ is a constant-time nonexistence proof that \emph{no} weights on a given architecture approximate $\tau^{\circ k}$ within $1/4$; the coefficients $a^{(c)}_i$ of Theorem~\ref{thm:onelayer} synthesise an exact single layer for $\tau^{\circ c}$ in $O(2^c)$ time; and Theorem~\ref{thm:bracket} yields, for any $(L,w)$ with $w\ge3$, the interval $\bigl[\lfloor\log_2(w-1)\rfloor L,\ (\lfloor\log_2(w-1)\rfloor+3)L+2\bigr]$ containing the maximal exactly computable tower height.

\section{Future work}

\begin{enumerate}
\item \textbf{A witness for a one-step separation.} Find, or rule out, a family $g_L$ computed by depth-$(L{+}1)$ networks of size $\mathrm{poly}(L)$ such that every depth-$L$ approximator within $1/4$ has size $2^{\Omega(L)}$. The collapse theorems show that the oscillation invariant cannot supply one; a measure that cannot grow by a bounded factor per layer at bounded width is needed.
\item \textbf{Closing the base gap.} Determine the exact maximal tower height $k^\star(L,2^c+1)$ between $cL$ and $(c+3)L+2$; a tight per-layer knot count should push $c+3$ toward $c+1$.
\item \textbf{Tolerance and norm dependence.} Track the dependence of the master inequality on $\varepsilon\in(0,1/2)$ and establish an $L^2$ analogue of Theorem~\ref{thm:l1} with an absolute constant.
\item \textbf{Genuinely multivariate witnesses.} Theorem~\ref{thm:ridge} transfers separations only for functions of one coordinate; for targets folding along several directions one expects bounds improving with $D$, invisible to the restriction technique.
\item \textbf{Other piecewise-affine activations and residual connections.} The knot calculus applies verbatim with the per-layer factor equal to the number of activation pieces; residual connections do not increase knot counts, so exact trade-offs for realistic architectures are within reach.
\item \textbf{Learning-theoretic consequences.} Converting the density statement of Theorem~\ref{thm:density} into a distribution-free sample-complexity separation under the uniform measure would connect this expressivity story to statistical learning theory.
\end{enumerate}

