"""Exact single-layer synthesis of a sawtooth tower.

For every c >= 1 the height-c tower tau^c is a SINGLE rectifier layer:

    tau^c(y) = sum_{i=0}^{2^c} a_i relu(y - i / 2^c),
    a_0 = a_{2^c} = 2^c,   a_i = (-1)^i 2^{c+1} otherwise.

Composing L such layers therefore computes tau^(cL) exactly at depth L and
width 2^c + 1. Synthesis costs O(2^c) time and memory; evaluation of the
resulting depth-L network costs O(L 2^c) arithmetic operations.
"""

from __future__ import annotations

from fractions import Fraction
from typing import List, Tuple

Layer = List[Tuple[Fraction, Fraction]]  # list of (breakpoint, coefficient)


def synthesise_tower_layer(c: int) -> Layer:
    """Return the (breakpoint, coefficient) pairs of the width-(2^c+1) layer
    computing tau^c exactly."""
    if c < 1:
        raise ValueError("c must be at least 1")
    n = 2 ** c
    layer: Layer = []
    for i in range(n + 1):
        coef = Fraction(n) if i in (0, n) else Fraction((-1) ** i * 2 * n)
        layer.append((Fraction(i, n), coef))
    return layer


def eval_layer(layer: Layer, y: Fraction) -> Fraction:
    """Evaluate a single rectifier layer with linear read-out."""
    total = Fraction(0)
    for shift, coef in layer:
        t = y - shift
        if t > 0:
            total += coef * t
    return total


def eval_deep_network(c: int, depth: int, y: Fraction) -> Fraction:
    """Evaluate the depth-`depth`, width-(2^c+1) network computing tau^(c*depth)."""
    layer = synthesise_tower_layer(c)
    out = Fraction(y)
    for _ in range(depth):
        out = eval_layer(layer, out)
    return out


def reference_tower(k: int, y: Fraction) -> Fraction:
    """tau^k computed by direct composition of the tent map (for verification)."""
    def tau(t: Fraction) -> Fraction:
        if t <= 0 or t >= 1:
            return Fraction(0)
        return 2 * t if t <= Fraction(1, 2) else 2 - 2 * t
    out = Fraction(y)
    for _ in range(k):
        out = tau(out)
    return out


def verify(c: int, depth: int, samples: int = 257) -> bool:
    """Check exactness of the synthesised network against direct composition."""
    return all(
        eval_deep_network(c, depth, Fraction(j, samples - 1))
        == reference_tower(c * depth, Fraction(j, samples - 1))
        for j in range(samples)
    )


if __name__ == "__main__":
    for c in (1, 2, 3):
        for depth in (1, 2, 3):
            print(f"c={c} depth={depth}: width {2**c+1} network equals "
                  f"tau^{c*depth} -> {verify(c, depth)}")
    print("\nCoefficients for c = 2 (the collapse of tau o tau):")
    for shift, coef in synthesise_tower_layer(2):
        print(f"    relu(y - {shift})  coefficient {coef}")

