"""Oscillation-counting certificate: turning sampled values into a knot lower bound.

Given the values of an unknown continuous piecewise affine function f at an
increasing list of sample points, count the alternations between the low band
[0, 1/4] and the high band [3/4, 1]. Each low-high-low (or high-low-high) triple
forces a knot strictly inside the corresponding interval, so

        (number of alternations) <= 2 * (number of knots) + 1.

This is a rigorous certificate: it lower-bounds the number of breakpoints of
ANY piecewise affine function taking the observed values, and hence, via the
knot budget 2 (2w+2)^L, lower-bounds the width of any network reproducing them.
Cost: O(number of samples).
"""

from __future__ import annotations

import math
from typing import Dict, List, Optional, Sequence


def band(value: float, low: float = 0.25, high: float = 0.75) -> Optional[int]:
    """Classify a value: 0 = low band, 1 = high band, None = neither."""
    if value <= low:
        return 0
    if value >= high:
        return 1
    return None


def count_alternations(values: Sequence[float]) -> int:
    """Longest chain of strict low/high alternations obtainable from the samples,
    read greedily from left to right."""
    chain: List[int] = []
    for v in values:
        b = band(v)
        if b is None:
            continue
        if not chain or chain[-1] != b:
            chain.append(b)
    return max(len(chain) - 1, 0)


def knot_lower_bound(values: Sequence[float]) -> int:
    """From m alternations conclude at least ceil((m-1)/2) knots."""
    m = count_alternations(values)
    return max((m - 1 + 1) // 2, 0)


def width_lower_bound(values: Sequence[float], depth: int) -> int:
    """Smallest width w consistent with the observed oscillations at the given
    depth, i.e. the least w with 2 (2w+2)^depth >= knot lower bound."""
    need = knot_lower_bound(values)
    if need == 0 or depth == 0:
        return 0
    w = 0
    while 2 * (2 * w + 2) ** depth < need:
        w += 1
    return w


def certificate(values: Sequence[float], depth: int) -> Dict[str, object]:
    m = count_alternations(values)
    knots = knot_lower_bound(values)
    return {
        "samples": len(values),
        "alternations": m,
        "knots_at_least": knots,
        "depth": depth,
        "width_at_least": width_lower_bound(values, depth),
        "implied_bound": f"{m} <= 2 * knots + 1",
    }


if __name__ == "__main__":
    def tau(t: float) -> float:
        if t <= 0.0 or t >= 1.0:
            return 0.0
        return 2 * t if t <= 0.5 else 2 - 2 * t

    def tower(k: int, t: float) -> float:
        for _ in range(k):
            t = tau(t)
        return t

    for k in (4, 6, 8, 10):
        pts = [i / 2 ** k for i in range(2 ** k + 1)]
        vals = [tower(k, p) for p in pts]
        cert = certificate(vals, depth=3)
        print(f"tau^{k:2d}: {cert}   (2^k = {2**k}, log2 width bound "
              f"{math.log2(cert['width_at_least'] + 1):.2f})")

